if (!defined('CLI_SCRIPT')) { define('CLI_SCRIPT', true); }
require('/www/moodle/config.php');
require_once($CFG->dirroot . '/lib/questionlib.php');
require_once($CFG->dirroot . '/question/format/xml/format.php');
require_once($CFG->dirroot . '/mod/quiz/lib.php');
require_once($CFG->dirroot . '/mod/quiz/locallib.php');
try {
    global $DB, $USER;
    $USER = get_admin();

    $course = $DB->get_record('course', ['shortname' => 'WORDSELECT01']);
    if (!$course) {
        throw new \RuntimeException("Course 'WORDSELECT01' was not found.");
    }

    $questionbanks = $DB->get_records('qbank', ['course' => $course->id]);
    if (count($questionbanks) !== 1) {
        throw new \RuntimeException("Expected one question bank for course 'WORDSELECT01'; found " . count($questionbanks) . '.');
    }
    $questionbank = reset($questionbanks);
    $questionbankcm = get_coursemodule_from_instance('qbank', $questionbank->id, $course->id);
    if (!$questionbankcm) {
        throw new \RuntimeException("The course-module record for the 'WORDSELECT01' question bank was not found.");
    }
    $questionbankcontext = context_module::instance($questionbankcm->id);
    $category = question_get_default_category($questionbankcontext->id, true);
    if (!$category) {
        throw new \RuntimeException("The default question category for course 'WORDSELECT01' was not found or created.");
    }

    $findquestion = static function (string $name) use ($DB, $category) {
        $sql = "SELECT q.*
                  FROM {question} q
                  JOIN {question_versions} qv ON qv.questionid = q.id
                  JOIN {question_bank_entries} qbe ON qbe.id = qv.questionbankentryid
                 WHERE qbe.questioncategoryid = :categoryid
                   AND q.qtype = :qtype
                   AND q.name = :name
              ORDER BY qv.version DESC, q.id DESC";
        $questions = $DB->get_records_sql($sql, [
            'categoryid' => $category->id,
            'qtype' => 'wordselect',
            'name' => $name,
        ], 0, 2);
        if (count($questions) > 1) {
            throw new \RuntimeException("More than one '{$name}' Wordselect question exists in the target category.");
        }
        return $questions ? reset($questions) : false;
    };

    $importquestion = static function (string $xml) use ($category, $questionbankcontext, $course) {
        $tmpdir = make_request_directory();
        $tmpfile = $tmpdir . '/wordselect.xml';
        if (file_put_contents($tmpfile, $xml) === false) {
            throw new \RuntimeException('Could not write the temporary Wordselect question import file.');
        }
        $qformat = new qformat_xml();
        $qformat->setCategory($category);
        $qformat->setContexts([$questionbankcontext]);
        $qformat->setCourse($course);
        $qformat->setFilename($tmpfile);
        $qformat->setMatchgrades('error');
        $qformat->setCatfromfile(false);
        $qformat->setContextfromfile(false);
        $qformat->setStoponerror(true);
        $qformat->set_display_progress(false);
        ob_start();
        try {
            $imported = $qformat->importpreprocess()
                && $qformat->importprocess()
                && $qformat->importpostprocess();
        } finally {
            ob_end_clean();
        }
        if (!$imported || count($qformat->questionids) !== 1) {
            throw new \RuntimeException('Moodle XML import did not create exactly one Wordselect question.');
        }
        return (int) reset($qformat->questionids);
    };

    // Three demo questions. Correct answers are read from the delimiters in the
    // question text, so defaultgrade must equal the number of correct items.
    $questiondefs = [
        'wordselect-001' => <<<'WORDSELECTXML'
<?xml version="1.0" encoding="UTF-8"?>
<quiz>
  <question type="wordselect">
    <name><text>wordselect-001</text></name>
    <questiontext format="html">
      <text><![CDATA[<p>The cat [sat] on the mat and [purred] quietly while the dog [slept] by the fire.</p>]]></text>
    </questiontext>
    <generalfeedback format="html">
      <text><![CDATA[<p>The verbs are sat, purred and slept.</p>]]></text>
    </generalfeedback>
    <defaultgrade>3.0000000</defaultgrade>
    <penalty>0.3333333</penalty>
    <hidden>0</hidden>
    <idnumber></idnumber>
    <introduction><![CDATA[<p>Select the verbs. Each incorrect word selected takes a mark off your total.</p>]]></introduction>
    <delimitchars>[]</delimitchars>
    <wordpenalty>1.0000000</wordpenalty>
    <correctfeedback format="html"><text>Your answer is correct.</text></correctfeedback>
    <partiallycorrectfeedback format="html"><text>Your answer is partially correct.</text></partiallycorrectfeedback>
    <incorrectfeedback format="html"><text>Your answer is incorrect.</text></incorrectfeedback>
    <hint format="html"><text>Try again</text></hint>
  </question>
</quiz>
WORDSELECTXML,
        'wordselect-002' => <<<'WORDSELECTXML'
<?xml version="1.0" encoding="UTF-8"?>
<quiz>
  <question type="wordselect">
    <name><text>wordselect-002</text></name>
    <questiontext format="html">
      <text><![CDATA[<p>Which city is the capital of France?</p><p>[Berlin]<br>[[Paris]]<br>[Madrid]<br>[Rome]</p>]]></text>
    </questiontext>
    <generalfeedback format="html">
      <text><![CDATA[<p>Double delimiters mark the correct item, so whole phrases can be selectable, like a multiple choice question.</p>]]></text>
    </generalfeedback>
    <defaultgrade>1.0000000</defaultgrade>
    <penalty>0.3333333</penalty>
    <hidden>0</hidden>
    <idnumber></idnumber>
    <introduction><![CDATA[<p>Multi-word mode: select the correct answer.</p>]]></introduction>
    <delimitchars>[]</delimitchars>
    <wordpenalty>1.0000000</wordpenalty>
    <correctfeedback format="html"><text>Your answer is correct.</text></correctfeedback>
    <partiallycorrectfeedback format="html"><text>Your answer is partially correct.</text></partiallycorrectfeedback>
    <incorrectfeedback format="html"><text>Your answer is incorrect.</text></incorrectfeedback>
    <hint format="html"><text>Try again</text></hint>
  </question>
</quiz>
WORDSELECTXML,
        'wordselect-003' => <<<'WORDSELECTXML'
<?xml version="1.0" encoding="UTF-8"?>
<quiz>
  <question type="wordselect">
    <name><text>wordselect-003</text></name>
    <questiontext format="html">
      <text><![CDATA[<p>The {dog} chased the {ball} across the {garden}.</p>]]></text>
    </questiontext>
    <generalfeedback format="html">
      <text><![CDATA[<p>This question uses curly braces as delimiters. The nouns are dog, ball and garden.</p>]]></text>
    </generalfeedback>
    <defaultgrade>3.0000000</defaultgrade>
    <penalty>0.3333333</penalty>
    <hidden>0</hidden>
    <idnumber></idnumber>
    <introduction><![CDATA[<p>Select the nouns.</p>]]></introduction>
    <delimitchars>{}</delimitchars>
    <wordpenalty>1.0000000</wordpenalty>
    <correctfeedback format="html"><text>Your answer is correct.</text></correctfeedback>
    <partiallycorrectfeedback format="html"><text>Your answer is partially correct.</text></partiallycorrectfeedback>
    <incorrectfeedback format="html"><text>Your answer is incorrect.</text></incorrectfeedback>
    <hint format="html"><text>Try again</text></hint>
  </question>
</quiz>
WORDSELECTXML,
    ];

    $questions = [];
    foreach ($questiondefs as $name => $xml) {
        $question = $findquestion($name);
        if (!$question) {
            $newid = $importquestion($xml);
            $question = $findquestion($name);
            if (!$question || (int) $question->id !== $newid) {
                throw new \RuntimeException("The imported '{$name}' question could not be retrieved from its category.");
            }
        }
        $questions[$name] = $question;
    }

    $quizzes = $DB->get_records('quiz', ['course' => $course->id, 'name' => 'Testing Wordselect!']);
    if (count($quizzes) !== 1) {
        throw new \RuntimeException("Expected one quiz named 'Testing Wordselect!' in course 'WORDSELECT01'; found " . count($quizzes) . '.');
    }
    $quiz = reset($quizzes);
    $quizcm = get_coursemodule_from_instance('quiz', $quiz->id, $course->id);
    if (!$quizcm) {
        throw new \RuntimeException("The course-module record for quiz 'Testing Wordselect!' was not found.");
    }
    $quiz->cmid = $quizcm->id;
    $quiz->cmidnumber = $quizcm->idnumber ?? '';

    if ((int) $quiz->cmid !== 2) {
        throw new \RuntimeException("Quiz 'Testing Wordselect!' must have course-module ID 2 for the configured landing page; found {$quiz->cmid}.");
    }

    // The declarative addModule step inserts the quiz record directly and never
    // creates the initial quiz_sections row that quiz_add_instance() provides;
    // quiz_start_new_attempt() requires it to build the attempt layout.
    if (!$DB->record_exists('quiz_sections', ['quizid' => $quiz->id])) {
        $DB->insert_record('quiz_sections', (object) ['quizid' => $quiz->id, 'firstslot' => 1, 'heading' => '', 'shufflequestions' => 0]);
    }

    foreach ($questions as $name => $question) {
        $questionbankentry = get_question_bank_entry($question->id);
        $assignedcount = $DB->count_records_sql(
            "SELECT COUNT(1)
               FROM {quiz_slots} slot
               JOIN {question_references} qr ON qr.itemid = slot.id
              WHERE slot.quizid = :quizid
                AND qr.component = :component
                AND qr.questionarea = :questionarea
                AND qr.questionbankentryid = :questionbankentryid",
            [
                'quizid' => $quiz->id,
                'component' => 'mod_quiz',
                'questionarea' => 'slot',
                'questionbankentryid' => $questionbankentry->id,
            ]
        );
        if ($assignedcount > 1) {
            throw new \RuntimeException("The '{$name}' question is assigned to the quiz more than once.");
        }
        if ($assignedcount === 0) {
            quiz_add_quiz_question($question->id, $quiz, 0, $question->defaultmark);
        }
    }

    $quizsettings = \mod_quiz\quiz_settings::create($quiz->id);
    $quizsettings->get_grade_calculator()->recompute_quiz_sumgrades();
    $quiz = $DB->get_record('quiz', ['id' => $quiz->id]);
    if (!$quiz || (float) $quiz->sumgrades !== 7.0 || (float) $quiz->grade !== 7.0) {
        throw new \RuntimeException('Quiz grade and sum-of-grades must both equal 7.');
    }
    $quiz->cmid = $quizcm->id;
    $quiz->cmidnumber = $quizcm->idnumber ?? '';
    quiz_update_grades($quiz);

    echo "Provisioned quiz 'Testing Wordselect!' with 3 Wordselect questions at cmid={$quiz->cmid}.\n";
} catch (\Throwable $e) {
    fwrite(STDERR, 'Wordselect quiz provisioning failed: ' . $e->getMessage() . "\n");
}
